#include <utility>
#include <vector>

std::pair<int, int> closestPoint(const std::vector<std::pair<int, int>>& points) {
    std::pair<int, int> best = points[0];
    int bestDist = best.first * best.first + best.second * best.second;
    for (const auto& [x, y] : points) {
        int dist = x * x + y * y;
        if (dist < bestDist) {
            best = {x, y};
            bestDist = dist;
        }
    }
    return best;
}

int main() {
    int n;
    std::cin >> n;
    std::vector<std::pair<int, int>> points;
    for (int i = 0; i < n; i++) {
        int x, y;
        std::cin >> x >> y;
        points.push_back({x, y});
    }
    auto [x, y] = closestPoint(points);
    std::cout << x << " " << y << "\n";
    return 0;
}

