        int bestDist = best.x * best.x + best.y * best.y;
        for (Point p : points) {
            int dist = p.x * p.x + p.y * p.y;
            if (dist < bestDist) {
                best = p;
                bestDist = dist;
            }
        }
        return best;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        List<Point> points = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int x = in.nextInt();
            int y = in.nextInt();
            points.add(new Point(x, y));
